package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseQ3MigrationTest extends MigrationTestSupport {
 @Test void populatedQ2RollsBackPartialQ3AndRetriesWithoutSeedingOperationalApprovals(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_q3_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("86").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
  try{UUID who=db.queryForObject("INSERT INTO users(email,password_hash,status,email_verified) VALUES('q3-upgrade@example.test','synthetic-only','ACTIVE',TRUE) RETURNING id",UUID.class);UUID support=db.queryForObject("INSERT INTO support_requests(user_id,email,message) VALUES(?,'q3-upgrade@example.test','SYNTHETIC_Q2_SOURCE_UNCOPIED') RETURNING id",UUID.class,who);db.update("INSERT INTO trust_cases(source_kind,source_id,domain,category,severity,purpose) VALUES('SUPPORT_REQUEST',?,'ACCOUNT','ACCOUNT_ACCESS','MEDIUM','SAFETY_COORDINATION')",support);var before=db.queryForList("SELECT id,source_kind,source_id,state,revision FROM trust_cases");db.execute("CREATE TABLE operation_alerts(synthetic_conflict INTEGER)");assertThatThrownBy(()->Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate()).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.tables WHERE table_schema=? AND table_name='operation_incidents'",Integer.class,schema)).isZero();db.execute("DROP TABLE operation_alerts");var flyway=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load();flyway.migrate();flyway.validate();assertThat(db.queryForList("SELECT id,source_kind,source_id,state,revision FROM trust_cases")).isEqualTo(before);for(String table:List.of("operation_incidents","operation_alert_routes","operation_ranking_audits","operation_communications"))assertThat(db.queryForObject("SELECT count(*) FROM "+table,Integer.class)).isZero();assertThat(db.queryForObject("SELECT message FROM support_requests WHERE id=?",String.class,support)).isEqualTo("SYNTHETIC_Q2_SOURCE_UNCOPIED");}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}
 }
}
